input.new_string:
function trim(s) {
  return s.trim();
}

function slugify(s) {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { trim, slugify };

input.command:
node -e '
const { slugify } = require("./src/str");
const samples = ["", "   ", "!!!", "-a-", "a  b", "A!@#B", "--x--y--", "9", "héllo", "日本", "a-b_c d", "  --Hello, World!--  "];
let bad = 0;
for (const s of samples) {
  const o = slugify(s);
  const checks = {
    idempotent: slugify(o) === o,
    noDoubleDash: !o.includes("--"),
    noEdgeDash: o === "" || (!o.startsWith("-") && !o.endsWith("-")),
    charset: /^[a-z0-9-]*$/.test(o),
  };
  const fails = Object.entries(checks).filter(([,v]) => !v).map(([k]) => k);
  if (fails.length) bad++;
  console.log(JSON.stringify(s).padEnd(26), "->", JSON.stringify(o).padEnd(22), fails.length ? "FAIL: " + fails : "ok");
}
console.log(bad ? "property violations: " + bad : "all properties hold");
'

